function testReadRain() {
  const data = { daily: { time: ["2026-09-26", "2026-09-27"], precipitation_sum: [0, 1.7] } }
  console.log(readRain(data))
}

function readRain(data) {
  const dates = data.daily.time
  const rain = data.daily.precipitation_sum
  let text = ""
  for (let i = 0; i < dates.length; i++) {
    if (i > 0) {
      text += "; "
    }
    text += `${dates[i]}: ${rain[i]} mm`
  }
  return text
}
